parameters.jsCode:
// Calculate real metrics from Nutshell data
const items = $input.all();
const today = new Date();
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);

// Extract data from merged inputs
const newContactsData = items.find(i => i.json.method === 'find' && i.json.params?.entity === 'Contact') || {};
const wonLeadsData = items.find(i => i.json.params?.entity === 'Lead' && i.json.params?.criteria?.currentStage === 'won') || {};
const openLeadsData = items.find(i => i.json.params?.entity === 'Lead' && i.json.params?.criteria?.status === 'open') || {};
const lostLeadsData = items.find(i => i.json.params?.entity === 'Lead' && i.json.params?.criteria?.currentStage === 'lost') || {};

// Parse totalResults from Nutshell responses
const newLeads = parseInt(newContactsData.json?.totalResults || 0);
const dealsWon = parseInt(wonLeadsData.json?.totalResults || 0);
const dealsLost = parseInt(lostLeadsData.json?.totalResults || 0);
const totalOpenLeads = parseInt(openLeadsData.json?.totalResults || 0);

// Calculate pipeline value from open leads
let pipelineValue = 0;
const openResults = openLeadsData.json?.results || [];
for (const lead of openResults) {
  const value = parseFloat(lead.value || lead.expectedValue || 0);
  pipelineValue += value;
}

// Calculate won revenue
let revenue = 0;
const wonResults = wonLeadsData.json?.results || [];
for (const lead of wonResults) {
  const value = parseFloat(lead.value || lead.expectedValue || 0);
  revenue += value;
}

// Conversion rates
const totalDeals = dealsWon + dealsLost;
const conversionRate = totalDeals > 0 ? ((dealsWon / totalDeals) * 100).toFixed(1) : '0';
const winRate = (newLeads > 0) ? ((dealsWon / newLeads) * 100).toFixed(1) : '0';

// Fetch intent signals from PostgreSQL (simplified - in production use a separate node)
// const highIntentLeads = await postgres.query("SELECT COUNT(*) FROM intent_signals WHERE intent_level IN ('boiling', 'immediate', 'declared')");

return [{
  json: {
    date: yesterday.toLocaleDateString('pt-BR'),
    new_leads: newLeads,
    deals_won: dealsWon,
    deals_lost: dealsLost,
    revenue: revenue.toFixed(2),
    pipeline_value: pipelineValue.toFixed(2),
    total_open_leads: totalOpenLeads,
    conversion_rate: conversionRate,
    win_rate: winRate,
    // These would come from PostgreSQL in a complete version:
    meetings_scheduled: 0, // TODO: query activities with type='meeting'
    proposals_sent: 0,     // TODO: query activities with type='proposal'
    manual_distribution_requested: 0, // TODO: query manual distribution requests for yesterday
    high_intent_leads: 0,  // TODO: query intent_signals WHERE intent_level IN ('boiling','immediate','declared')
    _raw_won_leads: wonResults.map(l => ({name: l.name, value: l.value, stage: l.currentStage})),
    _raw_open_leads: openResults.map(l => ({name: l.name, value: l.value, stage: l.currentStage}))
  }
}];

